DROP TABLE IF EXISTS `articles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `articles` (
  `id` varchar(255) COLLATE utf8mb4_spanish2_ci NOT NULL,
  `title` text COLLATE utf8mb4_spanish2_ci NOT NULL,
  `abstract_text` text COLLATE utf8mb4_spanish2_ci,
  `authors` json DEFAULT (json_array()),
  `journal_id` varchar(255) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `journal_title` varchar(500) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `publication_date` date DEFAULT NULL,
  `keywords` json DEFAULT (json_array()),
  `doi` varchar(255) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `url` text COLLATE utf8mb4_spanish2_ci,
  `language` varchar(50) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `source` varchar(50) COLLATE utf8mb4_spanish2_ci DEFAULT 'doaj',
  `last_updated` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_articles_pub_date` (`publication_date`),
  KEY `idx_articles_journal_id` (`journal_id`),
  KEY `idx_articles_doi` (`doi`),
  FULLTEXT KEY `ft_articles_search` (`title`,`abstract_text`),
  CONSTRAINT `fk_articles_journal` FOREIGN KEY (`journal_id`) REFERENCES `journals` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish2_ci;
