DROP TABLE IF EXISTS `books`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `books` (
  `id` char(36) COLLATE utf8mb4_spanish2_ci NOT NULL,
  `titulo` varchar(500) COLLATE utf8mb4_spanish2_ci NOT NULL,
  `autor` varchar(500) COLLATE utf8mb4_spanish2_ci NOT NULL,
  `isbn` varchar(50) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `editorial` varchar(255) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `anio_publicacion` int DEFAULT NULL,
  `categoria_id` bigint DEFAULT NULL,
  `ubicacion_id` bigint DEFAULT NULL,
  `cantidad_total` int NOT NULL DEFAULT '1',
  `cantidad_disponible` int NOT NULL DEFAULT '1',
  `codigo_barras` varchar(100) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `imagen_portada_url` text COLLATE utf8mb4_spanish2_ci,
  `estado` enum('disponible','prestado','da??ado','perdido') COLLATE utf8mb4_spanish2_ci DEFAULT 'disponible',
  `coleccion` varchar(255) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `numero_inventario` varchar(100) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `fecha_ingreso` date DEFAULT NULL,
  `formato_material` varchar(100) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `idioma` varchar(100) COLLATE utf8mb4_spanish2_ci DEFAULT 'Espa??ol',
  `numero_clasificacion` varchar(100) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `titulo_paralelo` varchar(500) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `numero_ejemplar` int DEFAULT '1',
  `lugar_publicacion` varchar(255) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `mencion_serie` varchar(255) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `numero_paginas` varchar(50) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `terminos_tematicos` text COLLATE utf8mb4_spanish2_ci,
  `fecha_adquisicion` date DEFAULT NULL,
  `precio` decimal(10,2) DEFAULT NULL,
  `orden_compra` varchar(100) COLLATE utf8mb4_spanish2_ci DEFAULT NULL,
  `nota` text COLLATE utf8mb4_spanish2_ci,
  `resena` text COLLATE utf8mb4_spanish2_ci,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo_barras` (`codigo_barras`),
  KEY `fk_books_category` (`categoria_id`),
  KEY `fk_books_location` (`ubicacion_id`),
  KEY `idx_books_titulo` (`titulo`(100)),
  KEY `idx_books_autor` (`autor`(100)),
  KEY `idx_books_isbn` (`isbn`),
  KEY `idx_books_coleccion` (`coleccion`),
  KEY `idx_books_idioma` (`idioma`),
  KEY `idx_books_formato` (`formato_material`),
  KEY `idx_books_num_inv` (`numero_inventario`),
  KEY `idx_books_num_clas` (`numero_clasificacion`),
  FULLTEXT KEY `ft_books_search` (`titulo`,`autor`,`isbn`,`editorial`,`numero_clasificacion`,`terminos_tematicos`,`numero_inventario`,`coleccion`,`codigo_barras`,`resena`),
  CONSTRAINT `fk_books_category` FOREIGN KEY (`categoria_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_books_location` FOREIGN KEY (`ubicacion_id`) REFERENCES `locations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish2_ci;
